// The base layouts: where the 26 letters sit. Only placement changes; the
// typing is the same on every layout, since the engine only ever sees letters.

struct Layout { let code: String; let label: String; let rows: [String] }

enum Layouts {
    static let all: [Layout] = [
        Layout(code: "qwerty", label: "QWERTY", rows: ["qwertyuiop", "asdfghjkl", "zxcvbnm"]),
        Layout(code: "qwertz", label: "QWERTZ", rows: ["qwertzuiop", "asdfghjkl", "yxcvbnm"]),
        Layout(code: "azerty", label: "AZERTY", rows: ["azertyuiop", "qsdfghjklm", "wxcvbn"]),
        Layout(code: "dvorak", label: "Dvorak", rows: ["pyfgcrl", "aoeuidhtns", "qjkxbmwvz"]),
        Layout(code: "colemak", label: "Colemak", rows: ["qwfpgjluy", "arstdhneio", "zxcvbkm"])]

    static func get(_ code: String) -> Layout { all.first { $0.code == code } ?? all[0] }
}
